func TestRunSuccess(t *testing.T) {
	fake := &fakePlugin{}
	oldPlugin, oldGetwd := newPlugin, getwd
	newPlugin = func(cfg plugin.Config) gitPlugin {
		if cfg.TagName != "v1.2.3" || cfg.Branch != "main" || len(cfg.Files) != 2 {
			t.Fatalf("unexpected config: %+v", cfg)
		}
		return fake
	}
	getwd = func() (string, error) { return "C:\\repo", nil }
	defer func() { newPlugin, getwd = oldPlugin, oldGetwd }()

	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_TAG_NAME":             "v1.2.3",
		"SEMREL_BRANCH":               "main",
		"SEMREL_PLUGIN_FILES":         "CHANGELOG.md, README.md",
		"SEMREL_PLUGIN_SIGN_TAG":      "true",
		"SEMREL_PLUGIN_SIGNED_OFF_BY": "true",
	}), &stdout, &stderr)
	if code != 0 || stderr.String() != "plugin_schema_version=1\n" {
		t.Fatalf("unexpected result: code=%d stderr=%q", code, stderr.String())
	}
	if got := len(fake.calls); got != 3 {
		t.Fatalf("expected 3 calls, got %v", fake.calls)
	}
	if fake.version != "1.2.3" || fake.dir != "C:\\repo" {
		t.Fatalf("unexpected run args: dir=%s version=%s", fake.dir, fake.version)
	}
}

func TestRunDryRun(t *testing.T) {
	called := false
	oldPlugin := newPlugin
	newPlugin = func(plugin.Config) gitPlugin {
		called = true
		return &fakePlugin{}
	}
	defer func() { newPlugin = oldPlugin }()

	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_TAG_NAME":     "v1.2.3",
		"SEMREL_PLUGIN_FILES": "CHANGELOG.md, package.json",
		"SEMREL_DRY_RUN":      "true",
	}), &stdout, &stderr)
	if code != 0 || called {
		t.Fatalf("unexpected result: code=%d called=%v", code, called)
	}
	if !strings.HasPrefix(stderr.String(), "plugin_schema_version=1\n") {
		t.Fatalf("missing schema version header: %q", stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-gitplugin: would commit [CHANGELOG.md package.json] (\"chore: release 1.2.3\"), create tag v1.2.3, and push branch main and tag v1.2.3 to origin") {
		t.Fatalf("unexpected stderr: %q", stderr.String())
	}
	var out dryRunOutput
	if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
		t.Fatalf("unmarshal dry-run stdout: %v (raw=%q)", err, stdout.String())
	}
	if out.Destination != "origin" || out.Branch != "main" || out.Tag != "v1.2.3" || out.CommitMessage != "chore: release 1.2.3" || len(out.Files) != 2 {
		t.Fatalf("unexpected dry-run output: %+v", out)
	}
}

func TestRunDryRunMasksRemoteCredentials(t *testing.T) {
	var stdout, stderr bytes.Buffer
	secret := "ghp_super_secret_git_token"
	code := run(context.Background(), env(map[string]string{
		"SEMREL_TAG_NAME":      "v2.0.0",
		"SEMREL_PLUGIN_REMOTE": "https://x-access-token:" + secret + "@github.com/SemRels/semrel.git",
		"SEMREL_DRY_RUN":       "true",
	}), &stdout, &stderr)
	if code != 0 {
		t.Fatalf("unexpected exit code: %d", code)
	}
	if strings.Contains(stdout.String(), secret) || strings.Contains(stderr.String(), secret) {
		t.Fatalf("secret leaked in output: stdout=%q stderr=%q", stdout.String(), stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-gitplugin: would create tag v2.0.0 and push branch main and tag v2.0.0 to https://x-access-token:%2A%2A%2A@github.com/SemRels/semrel.git") &&
		!strings.Contains(stderr.String(), "github.com/SemRels/semrel.git") {
		t.Fatalf("unexpected stderr: %q", stderr.String())
	}
}

